import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/03-Why-is-the-Father-of-the-Computer-a-fraud.html","title":"04-“计算机之父”为啥被当成骗子？","lang":"zh-CN","frontmatter":{"title":"04-“计算机之父”为啥被当成骗子？","icon":"read","date":"2025-04-11T22:09:49.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1744381022000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":11,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"b93c4865f3d80773d2308ecffc188c68873ba7a7","time":1744381022000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"你好，我是悦创。"},{"hash":"daad8395bc1302e1c2b7f2ee152b219638e30c37","time":1744380988000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"05-“计算机之父”为啥被当成骗子？"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.96,"words":2387},"filePathRelative":"column/Programmingthinking/03-Why-is-the-Father-of-the-Computer-a-fraud.md"}`),a={name:`03-Why-is-the-Father-of-the-Computer-a-fraud.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>上一讲，我跟你解释清楚了一个问题，<strong>编程就是告诉机器要做什么样的事情，该怎么做</strong>。我还特地跟你强调了一下，这句话里说的是“机器”而不是电脑，或者说计算机。因为上一讲里提到的两位发明家跟计算机没啥关系。</p><p>但今天说的这一位大科学家，倒跟计算机有关——有些人认为，他就是“<strong>计算机之父</strong>”。只不过，他发明的机器，仍然跟咱们今天的计算机不太一样。不过，他那台机器，可是<strong>超级厉害</strong>。有多厉害呢，你听我慢慢说，就明白了。</p><p>这位科学家的名字叫<strong>查尔斯·巴贝奇</strong>。巴贝奇小时候可能跟你一样，充满了好奇心，尤其是对各种<strong>机械</strong>。他喜欢把玩具、闹钟啥的<strong>拆个稀巴烂</strong>——你一定也这样做过吧？而且很可能你拆完了就装不回去了，或者装是装回去了，但多了零件出来。巴贝奇就不是这样了，他拆完任何东西，都可以<strong>原模原样</strong>装回去。</p><figure><img src="/assets/d174f1506a9b57dd3d1da54fd28a166b-DV49-6VM.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>除了在机械上很有天赋，巴贝奇还是一个实打实的数学天才。他轻轻松松考进了<strong>剑桥大学三一学院</strong>。三一学院你可能没听说过，但大名鼎鼎的牛顿，也是从这里毕业的。</p><figure><img src="/assets/d774d116b11fd9064014c665615f5c15-Ct2i1k-R.jpg" alt="剑桥大学三一学院" tabindex="0" loading="lazy"><figcaption>剑桥大学三一学院</figcaption></figure><p>在这么厉害的地方，巴贝奇是不是能学到更多厉害的知识呢？巴贝奇一开始也是这么想的，可学着学着巴贝奇就觉得不对劲了，这老师的水平怎么还不如自己高呢？老师不如自己，那巴贝奇就自己想办法去学。</p><p>后来，巴贝奇成了<strong>剑桥大学的数学教授</strong>——注意哦，他还不是一个普通的数学教授，而是一个拥有<strong>特别头衔</strong>的数学教授。这个头衔啊，在同一时间，只能有一个人拥有，特别厉害。大名鼎鼎的物理学家<strong>牛顿</strong>，以及著名的<strong>霍金</strong>，都曾经拥有过这个头衔——你就可以想象，巴贝奇有多厉害了。</p><p>更厉害的是，巴贝奇还通过自己的数学知识和机械知识，拯救了无数人的生命——因为他改进了“<strong>数学用表</strong>”。</p><p>诶，啥是“数学用表”啊？其实，数学用表，就是事先把一些特殊计算的结果算出来，印成一本书。如果你在计算当中，要用到这些特殊计算了，翻一下这个数学用表，就可以直接知道结果了。</p><p>比如说吧，你一定学过<strong>九九乘法表</strong>。九九乘法表就是一种简单的数学用表。在航海以及天文观测上，会用到很多复杂的数学用表。</p><p>不过，当时这些数学用表都是<strong>手工计算</strong>的，难免会出错。你的九九乘法表背错了没关系，顶多也就写错几道作业题，可航海用的表要是出错了，那船走的<strong>航线</strong>就会出错，很可能就会导致海难，是会出人命的。</p><p>怎么办呢？巴贝奇想到了，人会不小心算错，但机器不会呀。于是，他就试着用<strong>机器代替人工</strong>计算。不过，这些复杂的数学用表可不是用简单的加减乘除就能算出来的——而需要用到很复杂的数学运算。那么复杂的计算，当时的计算器可做不了。</p><p>怎么办呢？巴贝奇就自己造了一台能做这种复杂计算的机器，叫<strong>差分机</strong>。</p><figure><img src="/assets/ss-DYYSh9b_.jpg" alt="差分机的未完成作品" tabindex="0" loading="lazy"><figcaption>差分机的未完成作品</figcaption></figure><p>巴贝奇先是造了一台<strong>功能简单</strong>的差分机。这台简化版的机器表现得特别好，用它做的数学用表几乎没有什么错误，巴贝奇很受鼓舞，于是想做一台真正的、<strong>完全符合自己设计</strong>的差分机。英国政府也特别支持他，出钱<strong>支持</strong>他造机器。</p><p>可是造着造着，巴贝奇就觉得不对劲了，差分机的<strong>精度</strong>要求太<strong>高</strong>了，有些零件，精度误差甚至不能超过0.03毫米，这是什么概念呢？比一根头发丝还细。这要求在当时根本就做不到。</p><p>英国政府花了好多钱让巴贝奇造真正的差分机。结果，钱快花完了，却还没见着差分机的影子。英国政府受不了了<strong>，停止了资助</strong>，还拿走了很多零件。</p><p>巴贝奇的梦想算是彻底破灭了，他甚至被当成一个<strong>骗子</strong>，名誉扫地。有意思的是，在1991年，人们按照巴贝奇的方法真的造出了一台<strong>真正的差分机</strong>。巴贝奇并不是骗子，只是他生活的时代，还配不上他的思想罢了。</p><p>咱们说回到巴贝奇，差分机是没法造了，可他没有闲着，又开始琢磨另一件厉害的东西，叫<strong>分析机</strong>——今天所有的计算机都和分析机有关。</p><p>那什么是分析机呢？</p><p>巴贝奇想，之前的差分机只能拿来做<strong>一种</strong>数学计算，而且还要花那么多钱，实在是太不划算了，我能不能造一台机器，能完成好<strong>多种</strong>计算呢？</p><p>那怎么让一台机器完成好多种运算呢？巴贝奇就想，机器可以是固定的，但我可以往机器里插入不同的“<strong>卡</strong>”啊。这些卡上都提前打好了孔，就有点像前一讲说的打孔纸。这些孔记录着规则，告诉机器该怎么工作。</p><p>这样一来，只要换不同的卡，机器就能干不同的工作了。巴贝奇的这个想法，引起了一位<strong>女数学家</strong>的兴趣，她叫<strong>埃达</strong>。</p><figure><img src="/assets/35cfe22cb05d30d51cf6fcaea974531e-BWiesRMN.jpg" alt="埃达的画像" tabindex="0" loading="lazy"><figcaption>埃达的画像</figcaption></figure><p>埃达觉得这个想法太棒了，要是真有这样一台机器，不光能做数学计算，还可以在各个方面给人们提供帮助。她甚至写了一些可以给分析机用的程序。</p><p>很多人认为，埃达写的这些程序，已经和今天计算机程序有不少相似的地方了。所以，很多人把埃达称为<strong>世界上第一位程序员</strong>——注意哦，世界上第一位程序员，是位<strong>女程序员</strong>哦。</p><p>顺便说一句，这位埃达还有一个很有名的地方，那就是，她的爸爸是英国最有名的浪漫主义诗人<strong>拜伦</strong>。</p><p>虽然埃达很重视分析机，但分析机却根本造不出来——它比差分机还要复杂。巴贝奇只完成了分析机的<strong>一小部分</strong>。现在，这一小部分还在<strong>伦敦科学博物馆</strong>里，如果你有机会去那里，可以亲眼看一看这台机器。</p><figure><img src="/assets/d4b665ef1196a92c4146ccd68c5e93a1-CIbHpAbt.jpg" alt="分析机" tabindex="0" loading="lazy"><figcaption>分析机</figcaption></figure><p>在巴贝奇之后，还有很多人使用类似的思路，制造了一些有意思的机器。比如，被尊为“<strong>人工智能之父</strong>”的<strong>图灵</strong>，就设计过一种叫“<strong>图灵机</strong>”的机器。图灵机是要用一条打着孔的纸条来让机器知道，接下来要做什么任务。你看，这个想法是不是和巴贝奇的分析机特别像？</p><p>那无论是图灵机还是巴贝奇的分析机，他们的思想都是建立一台通用的机器，根据你放入的程序不同，就能完成不同的任务。今天，人们就把这种计算机叫做<strong>通用式计算机</strong>。你今天用的手机、电脑都是通用式计算机，只要点开不同的程序，它就能完成不同的任务。</p><p>其实，这种<strong>建立通用模型</strong>的思想也特别重要，你要是学会了，对你的学习也特别有帮助。</p><p>比方说做数学应用题吧，应用题有那么多种，不可能把所有题目都记住，对吧？怎么办呢？咱们就可以建模型。</p><p>当然了，咱们也不可能建立一个模型能适用于所有的数学题，但没关系，你可以给一些相同的题目建模型，比如，你可能会经常碰到<strong>年龄问题</strong>，这一类问题就可以建立一个模型，甭管谁比谁大、谁比谁小，都想办法找他们的年龄差，这样你就可以<strong>举一反三</strong>了。同样的，你还可以建立追及问题模型、间隔问题模型等等等等。这就是建立通用模型的重要性。</p><p>那刚刚，咱们提到了图灵机，图灵机只是图灵提出的一种数学模型，并没有真的造出来，但是，图灵真的造出过一个机器，这个机器实实在在地<strong>改变</strong>了世界的走向。到底是什么厉害的机器呢？咱们下一集再说。</p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};